#!/usr/bin/env node
/**
 * SAF-F08 — schema-parity-from-prod
 *
 * ROOT DEFECT: docs/schema-parity-baseline.json is regenerated by parsing db/migrations/
 * (see verify-schema-parity.mjs). Held migrations with applied_on_prod:false still contribute
 * columns to that baseline, so verify-sql-column-existence can report "every checked column
 * exists" while production information_schema does not have them. That is the false-PASS that
 * let SAF-F02/F03/F04 look green from file-parse alone.
 *
 * THIS GUARD (CI-static, no live DB required):
 *   1. Collect ADD COLUMN targets from held migrations where applied_on_prod !== true
 *   2. Compare against docs/schema-parity-prod-evidence.json (prod information_schema snapshot)
 *   3. FAIL if the migration-parsed baseline lists a held-unapplied column ABSENT on prod evidence
 *   4. FAIL if safety-lane code references a held-unapplied column ABSENT on prod evidence
 *
 * --selftest plants the exact F02 shape (held/unapplied column in baseline + safety SQL) and
 * must FAIL. --update-from-db regenerates the evidence file from DATABASE_URL / DIRECT_URL.
 *
 * Prod wins. Migration parse is never sufficient for held-column truth.
 */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const LABEL = "verify-schema-parity-from-prod";
const HELD_MANIFEST = path.join(ROOT, "db/migrations/.held-migrations.json");
const MIGRATIONS_DIR = path.join(ROOT, "db/migrations");
const BASELINE_PATH = path.join(ROOT, "docs/schema-parity-baseline.json");
const EVIDENCE_PATH = path.join(ROOT, "docs/schema-parity-prod-evidence.json");
const CODE_DIRS = [
  "apps/backend/src/safety",
  "apps/backend/src/insurance",
  "apps/backend/src/driver-finance",
  "apps/backend/src/legal",
  "apps/frontend/src/pages/safety",
  "apps/frontend/src/components/safety",
];

const SELFTEST = process.argv.includes("--selftest");
const UPDATE_FROM_DB = process.argv.includes("--update-from-db");

const stripSql = (body) => body.replace(/--.*$/gm, "").replace(/\/\*[\s\S]*?\*\//g, "");

/** Safety-lane schemas where held-column false-PASS is in scope for SAF-F08. */
const SCOPE_SCHEMAS = new Set(["safety", "legal", "driver_finance", "insurance"]);

/** @returns {Map<string, { file: string, col: string, table: string }>} key = schema.table.column */
export function heldUnappliedColumns(manifest, readMig = (f) => fs.readFileSync(path.join(MIGRATIONS_DIR, f), "utf8")) {
  const out = new Map();
  for (const h of manifest.held ?? []) {
    if (h.applied_on_prod === true) continue;
    if (!h.file || !fs.existsSync(path.join(MIGRATIONS_DIR, h.file))) continue;
    const sql = stripSql(readMig(h.file));
    // ALTER TABLE schema.table … ADD COLUMN [IF NOT EXISTS] col
    // Non-greedy between ALTER and ADD so multiple ADD COLUMNs in one statement still match.
    const re =
      /ALTER\s+TABLE\s+(?:IF\s+EXISTS\s+)?([a-z_][a-z0-9_]*)\.([a-z_][a-z0-9_]*)\s+([\s\S]*?);/gi;
    let block;
    while ((block = re.exec(sql)) !== null) {
      const schema = block[1].toLowerCase();
      const table = block[2].toLowerCase();
      if (!SCOPE_SCHEMAS.has(schema)) continue;
      const body = block[3];
      for (const m of body.matchAll(/ADD\s+COLUMN\s+(?:IF\s+NOT\s+EXISTS\s+)?([a-z_][a-z0-9_]*)/gi)) {
        const col = m[1].toLowerCase();
        const key = `${schema}.${table}.${col}`;
        out.set(key, { file: h.file, col, table: `${schema}.${table}` });
      }
    }
  }
  return out;
}

function loadEvidence(p = EVIDENCE_PATH) {
  if (!fs.existsSync(p)) {
    throw new Error(`${LABEL}: missing ${path.relative(ROOT, p)} — commit a prod information_schema snapshot or run --update-from-db`);
  }
  const raw = JSON.parse(fs.readFileSync(p, "utf8"));
  const cols = raw.columns || raw.tables || {};
  const set = new Set();
  for (const [table, list] of Object.entries(cols)) {
    for (const c of list) set.add(`${String(table).toLowerCase()}.${String(c).toLowerCase()}`);
  }
  return { raw, set };
}

function loadBaseline(p = BASELINE_PATH) {
  const raw = JSON.parse(fs.readFileSync(p, "utf8"));
  const tables = raw.tables || raw;
  const set = new Set();
  for (const [table, list] of Object.entries(tables)) {
    if (!Array.isArray(list)) continue;
    for (const c of list) set.add(`${String(table).toLowerCase()}.${String(c).toLowerCase()}`);
  }
  return set;
}

function listCodeFiles(dirs = CODE_DIRS) {
  const out = [];
  const walk = (dir) => {
    const abs = path.join(ROOT, dir);
    if (!fs.existsSync(abs)) return;
    for (const e of fs.readdirSync(abs, { withFileTypes: true })) {
      const rel = path.join(dir, e.name);
      if (e.isDirectory()) {
        if (e.name === "node_modules" || e.name === "__tests__") continue;
        walk(rel);
      } else if (/\.(ts|tsx)$/.test(e.name)) out.push(rel);
    }
  };
  for (const d of dirs) walk(d);
  return out;
}

/** True when identifier appears inside a SQL-ish string literal in safety-lane code. */
export function safetyCodeReferences(columnName, files = listCodeFiles()) {
  const hits = [];
  const colRe = new RegExp(`\\b${columnName}\\b`);
  for (const rel of files) {
    const body = fs.readFileSync(path.join(ROOT, rel), "utf8");
    for (const m of body.matchAll(/`([^`]*)`|"([^"]*)"|'([^']*)'/g)) {
      const text = m[1] ?? m[2] ?? m[3] ?? "";
      if (!/\b(SELECT|INSERT|UPDATE|DELETE|FROM|SET|VALUES|WHERE|JOIN|RETURNING)\b/i.test(text)) continue;
      if (colRe.test(text)) {
        hits.push(rel);
        break;
      }
    }
  }
  return hits;
}

/**
 * Core assertion used by CI and --selftest.
 * @returns {string[]} problem lines
 */
export function assertParityFromProd({ heldCols, baselineSet, evidenceSet, codeHitsFor }) {
  const problems = [];
  for (const [key, meta] of heldCols) {
    const onProd = evidenceSet.has(key);
    if (onProd) continue; // held flag stale OR applied out of band — prod wins, not a defect
    const inBaseline = baselineSet.has(key);
    const hits = codeHitsFor(meta.col);
    if (inBaseline) {
      problems.push(
        `FALSE-PASS: baseline lists ${key} from held ${meta.file} (applied_on_prod≠true) but prod evidence ABSENT — ` +
          `schema-parity baseline is migration-parsed, not prod (SAF-F08)`
      );
    }
    if (hits.length) {
      problems.push(
        `PHANTOM CONSUMER: ${hits[0]} references ${meta.col} (${key}) from held ${meta.file} ` +
          `with applied_on_prod≠true and ABSENT on prod evidence — apply via HELD ceremony or stop reading it`
      );
    }
  }
  return problems;
}

async function updateEvidenceFromDb() {
  const require = createRequire(import.meta.url);
  const { buildPgClientConfig } = require("./lib/pg-connection-options.cjs");
  try {
    (await import("dotenv")).default.config();
  } catch {
    /* optional */
  }
  const cs = process.env.DATABASE_DIRECT_URL || process.env.DATABASE_URL;
  if (!cs) {
    console.error(`${LABEL}: --update-from-db needs DATABASE_URL or DATABASE_DIRECT_URL`);
    process.exit(1);
  }
  const pg = (await import("pg")).default;
  const client = new pg.Client(buildPgClientConfig(cs, { connectionTimeoutMillis: 20000 }));
  await client.connect();
  try {
    await client.query(`SELECT set_config('app.bypass_rls','lucia',true)`);
    const { rows } = await client.query(`
      SELECT table_schema || '.' || table_name AS rel, column_name
        FROM information_schema.columns
       WHERE table_schema IN ('safety','legal','driver_finance','insurance','accounting','banking','catalogs','mdata')
       ORDER BY 1, 2
    `);
    const columns = {};
    for (const r of rows) {
      (columns[r.rel] ??= []).push(r.column_name);
    }
    const out = {
      note:
        "Prod information_schema snapshot (SET app.bypass_rls='lucia'). Source of truth for " +
        "verify-schema-parity-from-prod. Do not hand-invent columns. Regenerate: " +
        "node scripts/verify-schema-parity-from-prod.mjs --update-from-db",
      branch: "br-fancy-credit-akjnd07a",
      as_of: new Date().toISOString(),
      source: "information_schema.columns",
      columns,
    };
    fs.writeFileSync(EVIDENCE_PATH, JSON.stringify(out, null, 2) + "\n");
    console.log(`${LABEL}: wrote ${path.relative(ROOT, EVIDENCE_PATH)} (${Object.keys(columns).length} tables)`);
  } finally {
    await client.end().catch(() => {});
  }
}

function runSelftest() {
  const phantomKey = "safety.civil_fines.phantom_held_col_saf_f08";
  const phantomCol = "phantom_held_col_saf_f08";
  const heldCols = new Map([
    [phantomKey, { file: "209999990000_phantom_held_saf_f08.sql", col: phantomCol, table: "safety.civil_fines" }],
  ]);
  const baselineSet = new Set([phantomKey, "safety.civil_fines.id"]);
  const evidenceSet = new Set(["safety.civil_fines.id", "safety.civil_fines.driver_settlement_deduction_id"]);
  const codeHitsFor = (col) => (col === phantomCol ? ["apps/backend/src/safety/fines.routes.ts"] : []);

  const problems = assertParityFromProd({ heldCols, baselineSet, evidenceSet, codeHitsFor });
  if (problems.length < 2) {
    console.error(`${LABEL} SELFTEST FAILED: expected ≥2 problems for held/unapplied phantom (got ${problems.length})`);
    for (const p of problems) console.error(`  ${p}`);
    process.exit(1);
  }
  if (!problems.some((p) => /FALSE-PASS/.test(p)) || !problems.some((p) => /PHANTOM CONSUMER/.test(p))) {
    console.error(`${LABEL} SELFTEST FAILED: must report both FALSE-PASS and PHANTOM CONSUMER`);
    process.exit(1);
  }

  // Present-on-prod held column must NOT fail (the REFUTED F02 shape after out-of-band apply)
  const okProblems = assertParityFromProd({
    heldCols: new Map([
      [
        "safety.civil_fines.driver_settlement_deduction_id",
        { file: "202607080000_settlement_contract_terms.sql", col: "driver_settlement_deduction_id", table: "safety.civil_fines" },
      ],
    ]),
    baselineSet: new Set(["safety.civil_fines.driver_settlement_deduction_id"]),
    evidenceSet: new Set(["safety.civil_fines.driver_settlement_deduction_id"]),
    codeHitsFor: () => ["apps/backend/src/safety/fines.routes.ts"],
  });
  if (okProblems.length !== 0) {
    console.error(`${LABEL} SELFTEST FAILED: column present on prod evidence must not FAIL`);
    process.exit(1);
  }

  console.log(
    `${LABEL} SELFTEST PASS — held/unapplied phantom FAILS (FALSE-PASS + PHANTOM CONSUMER); prod-present held column is not a defect`
  );
}

async function main() {
  if (UPDATE_FROM_DB) {
    await updateEvidenceFromDb();
    return;
  }
  if (SELFTEST) {
    runSelftest();
    return;
  }

  const manifest = JSON.parse(fs.readFileSync(HELD_MANIFEST, "utf8"));
  const heldCols = heldUnappliedColumns(manifest);
  const baselineSet = loadBaseline();
  const { set: evidenceSet, raw: evidence } = loadEvidence();

  if (!evidence.branch || !evidence.source) {
    console.error(`${LABEL} FAILED: evidence file must declare branch + source (prod information_schema)`);
    process.exit(1);
  }
  if (!/information_schema/i.test(evidence.source)) {
    console.error(`${LABEL} FAILED: evidence.source must be information_schema — not migration parse`);
    process.exit(1);
  }

  // Baseline writer must remain migration-parsed (document the dual track) — we assert the committed
  // writer still says so, so nobody "fixes" F08 by lying that baseline is prod-derived.
  const writer = fs.readFileSync(path.join(ROOT, "scripts/verify-schema-parity.mjs"), "utf8");
  if (!/Parses all migration SQL files/i.test(writer) && !/parseMigrations/i.test(writer)) {
    console.error(`${LABEL} FAILED: verify-schema-parity.mjs no longer parses migrations — update this guard`);
    process.exit(1);
  }
  if (/information_schema/i.test(writer) && /--update/.test(writer) && /FROM information_schema/i.test(writer)) {
    // If someone later switches the writer to prod, this branch is fine — dual track collapses.
  }

  const problems = assertParityFromProd({
    heldCols,
    baselineSet,
    evidenceSet,
    codeHitsFor: (col) => safetyCodeReferences(col),
  });

  if (problems.length) {
    console.error(`${LABEL} FAILED (${problems.length}):`);
    for (const p of problems) console.error(`  ${p}`);
    console.error(
      `\nFix: Neon-apply the held migration + ledger-backfill + set applied_on_prod:true, ` +
        `OR stop referencing the column, OR refresh prod evidence (--update-from-db) if prod already has it.`
    );
    process.exit(1);
  }

  console.log(
    `${LABEL} OK — ${heldCols.size} held-unapplied ADD COLUMN(s) checked vs prod evidence ` +
      `(${evidence.branch}, as_of ${evidence.as_of || "?"}); no false-PASS / phantom consumers`
  );
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((e) => {
    console.error(`${LABEL} FAILED — ${e.message}`);
    process.exit(1);
  });
}
